        }
        .sheet(isPresented: $isAddingNew) {
            NavigationStack {
                QuickActionEditView(
                    action: CustomQuickAction(label: "", icon: "terminal", section: "AI", command: "")
                ) { newAction in
                    store.add(newAction)
                    isAddingNew = false
                }
            }
        }
    }
}

