import SwiftUI

struct PaneCardView: View {
    let title: String
    let isFocused: Bool
    let hasNotification: Bool
    let isTranscribing: Bool
    let transcript: String
    var terminalText: String = ""
    var isBrowser: Bool = false
    var screenshotData: Data?
    var browserURL: String = ""

    @State private var notificationPulse = false
    @State private var userScrolledUp = false
    @State private var lastContentLength = 0

    var body: some View {
        ZStack {
            // Glass background
            RoundedRectangle(cornerRadius: 12)
                .fill(.ultraThinMaterial.opacity(isFocused ? 0.4 : 0.2))
                .environment(\.colorScheme, .dark)

            // Notification pulse ring
            if hasNotification {
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.orange, lineWidth: 2.5)
                    .opacity(notificationPulse ? 0.4 : 1.0)
                    .animation(
                        .easeInOut(duration: 1.2).repeatForever(autoreverses: true),
                        value: notificationPulse
                    )
                    .onAppear { notificationPulse = true }
                    .onDisappear { notificationPulse = false }
            }

            // Focus glow border
            RoundedRectangle(cornerRadius: 12)
                .stroke(borderColor, lineWidth: isFocused ? 1.5 : 0.5)

            // Content
            VStack(spacing: 0) {
                // Title bar
                titleBar

                // Body area
                ZStack(alignment: .topLeading) {
                    if isTranscribing && !transcript.isEmpty {
                        Text(transcript)
                            .font(.system(size: 11, weight: .regular, design: .monospaced))
                            .foregroundColor(.green.opacity(0.8))
                            .lineLimit(4)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(.horizontal, 10)
                            .padding(.top, 8)
                    } else if isBrowser {
                        browserContentView
                    } else if !terminalText.isEmpty {
                        terminalContentView
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
            }
        }
        .shadow(color: isFocused ? .white.opacity(0.08) : .clear, radius: 12)
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .fill(isTranscribing ? Color.red.opacity(0.03) : .clear)
        )
    }

    // MARK: - Browser content

    private var browserContentView: some View {
        Group {
            if let data = screenshotData, let uiImage = UIImage(data: data) {
                Image(uiImage: uiImage)
                    .resizable()
                    .aspectRatio(contentMode: .fill)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                VStack(spacing: 8) {
                    Image(systemName: "globe")
                        .font(.system(size: 24))
                        .foregroundStyle(.white.opacity(0.2))
                    if !browserURL.isEmpty {
                        Text(browserURL)
                            .font(.system(size: 8, design: .monospaced))
                            .foregroundStyle(.white.opacity(0.3))
                            .lineLimit(2)
                            .multilineTextAlignment(.center)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        }
    }

    // MARK: - Terminal content

    private var terminalContentView: some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(spacing: 0) {
                    Text(terminalText)
                        .font(.system(size: isFocused ? 9 : 7, weight: .regular, design: .monospaced))
                        .foregroundStyle(.white.opacity(isFocused ? 0.85 : 0.5))
                        .lineSpacing(1)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 8)
                        .padding(.vertical, 6)

                    Color.clear.frame(height: 1).id("bottom")
                }
                .background(
                    GeometryReader { contentGeo in
                        Color.clear.preference(
                            key: ContentHeightKey.self,
                            value: contentGeo.frame(in: .named("termScroll")).minY
                        )
                    }
                )
            }
            .coordinateSpace(name: "termScroll")
            .onPreferenceChange(ContentHeightKey.self) { offset in
                // If content top is visible (offset >= -5), user is near the top
                // If offset is very negative, user is scrolled down / at bottom
                if let offset {
                    // Detect if user has scrolled away from bottom
                    // offset close to 0 or positive means we can see the top = scrolled up
                    userScrolledUp = offset > -20
                }
            }
            .simultaneousGesture(
                DragGesture(minimumDistance: 5)
                    .onChanged { value in
                        if value.translation.height > 0 {
                            // Scrolling up (dragging down)
                            userScrolledUp = true
                        }
                    }
                    .onEnded { _ in }
            )
            .onAppear {
                proxy.scrollTo("bottom", anchor: .bottom)
            }
            .onChange(of: terminalText) {
                let newLength = terminalText.count
                if !userScrolledUp {
                    // Only auto-scroll if user hasn't scrolled up
                    proxy.scrollTo("bottom", anchor: .bottom)
                }
                lastContentLength = newLength
            }
        }
    }

    // MARK: - Title bar

    private var titleBar: some View {
        HStack(spacing: 6) {
            // Surface type icon
            Image(systemName: isBrowser ? "globe" : "terminal")
                .font(.system(size: 9, weight: .medium))
